import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

function UserShop() {
  const navigate = useNavigate();
  const [medicines, setMedicines] = useState([]);
  const [cart, setCart] = useState([]);

  // Sample medicine data (you can replace it with database API later)
  useEffect(() => {
    const sampleMedicines = [
      { id: 1, name: "Paracetamol 500mg", description: "Fever & pain relief", price: 25 ,image: "\ Paracetamol-500.jpg" },
      { id: 2, name: "Amoxicillin 250mg", description: "Antibiotic", price: 80, image:"\ Amoxicillin 250mg.jpg" },
      { id: 3, name: "Ibuprofen 400mg", description: "Inflammation relief", price: 50,image:"\ Ibuprofen 400mg.jpg" },
      { id: 4, name: "Vitamin C Chewable", description: "Boosts immunity", price: 100, image:"\ Vitamin_C_Chewable.jpg"},
      { id: 5, name: "Amlodipine 5mg", description: "Blood pressure control", price: 120, image:"\ Amlodipine 5mg.jpg " },
    ];
    setMedicines(sampleMedicines);
  }, []);

  // Add item to cart
  const handleAddToCart = (medicine) => {
    const existingCart = JSON.parse(localStorage.getItem("cart")) || [];

    const existingItem = existingCart.find((item) => item.id === medicine.id);
    if (existingItem) {
      existingItem.quantity += 1;
    } else {
      existingCart.push({ ...medicine, quantity: 1 });
    }

    localStorage.setItem("cart", JSON.stringify(existingCart));
    setCart(existingCart);
    alert(`${medicine.name} added to cart!`);
  };

  // Go to cart page
  const goToCart = () => {
    navigate("/cart");
  };

  return (
    <div className="p-6 bg-gray-50 min-h-screen">
      <h1 className="text-3xl font-bold text-indigo-700 text-center mb-8">
        🏥 Online Medical Shop
      </h1>

      <div className="flex justify-end mb-4">
        <button
          onClick={goToCart}
          className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition"
        >
          View Cart ({cart.length})
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {medicines.map((medicine) => (
          <div
            key={medicine.id}
            className="bg-white p-4 rounded-xl shadow hover:shadow-lg transition"
          >
            <img 
            src={med.image}
            alt={med.name}
            className="w-32 h-32 object-cover rounded-md mb-3"></img>

            <h3 className="text-lg font-bold text-indigo-700"> {medicine.name}</h3>
            <p className="text-gray-600 text-sm mb-2">{medicine.description}</p>
            <p className="font-semibold text-green-600 mb-3">
              ₹{medicine.price.toFixed(2)}
            </p>
            <button
              onClick={() => handleAddToCart(medicine)}
              className="w-full bg-indigo-600 text-white py-2 rounded hover:bg-indigo-700"
            >
              Add to Cart
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

export default UserShop;

